import{_ as t,o as r,c as a,a5 as o}from"./chunks/framework.BZzouRtU.js";const s="/study/images/browser/xss-data-to-code.svg",n="/study/images/browser/csp-inline-handler-flow.svg",f=JSON.parse('{"title":"XSSとCSP — データがコードとして実行される境界","description":"","frontmatter":{"title":"XSSとCSP — データがコードとして実行される境界","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"browser","summary":"XSSが成立する入力と出力の経路、文字列をテキストやHTMLとして扱う処理の違い、CSPによるスクリプト実行の制限を説明する。","aliases":["XSS","Cross-Site Scripting","クロスサイトスクリプティング","反射型","蓄積型","DOM-based XSS","source","sink","textContent","innerHTML","出力エンコード","サニタイズ","CSP","Content Security Policy","script-src","script-src-attr","nonce","hash","Report-Only"],"verification":"WHATWG標準、W3CのCSP Level 3作業草案、OWASP資料と照合（2026-11-05）"}},"headers":[],"relativePath":"browser/xss-and-csp.md","filePath":"browser/xss-and-csp.md"}'),c={name:"browser/xss-and-csp.md"};function i(d,e,l,h,p,g){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="xssとcsp-—-データがコードとして実行される境界" tabindex="-1">XSSとCSP — データがコードとして実行される境界 <a class="header-anchor" href="#xssとcsp-—-データがコードとして実行される境界" aria-label="Permalink to &quot;XSSとCSP — データがコードとして実行される境界&quot;">​</a></h1><p><strong>XSS</strong>（Cross-Site Scripting）は、Webアプリが外部から受け取ったデータを扱う過程で、攻撃者が用意したコードを利用者のブラウザで実行できる脆弱性です。たとえばコメントをHTMLに埋め込むとき、コメントの一部がボタンの <code>onclick</code> 属性として解釈されると、そのコードがページの実行環境で動き得ます。対策はデータをどこから受け取り、どこで何として解釈させるかを確認するところから始まります。<a href="https://cheatsheetseries.owasp.org/cheatsheets/Cross_Site_Scripting_Prevention_Cheat_Sheet.html#xss-defense-philosophy" target="_blank" rel="noreferrer">OWASPのXSS対策</a></p><h2 id="入力から実行までをたどる" tabindex="-1">入力から実行までをたどる <a class="header-anchor" href="#入力から実行までをたどる" aria-label="Permalink to &quot;入力から実行までをたどる&quot;">​</a></h2><p><strong>source</strong> はデータの入口です。フォーム、URLのクエリやフラグメント、APIの応答、保存済みのコメントなどがあります。<strong>sink</strong> はデータの行き先で、値の意味を決めるAPIやテンプレートの出力箇所です。たとえばURLの値を <code>innerHTML</code> に渡すコードでは、受け取った文字列がHTMLとして解釈される経路を追います。<a href="https://cheatsheetseries.owasp.org/cheatsheets/DOM_based_XSS_Prevention_Cheat_Sheet.html" target="_blank" rel="noreferrer">OWASPのDOM Based XSS対策</a></p><table tabindex="0"><thead><tr><th>呼び方</th><th>データがページに届く経路の例</th></tr></thead><tbody><tr><td>反射型（reflected）</td><td>リクエストの検索語が、そのリクエストに対するHTML応答に埋め込まれる。</td></tr><tr><td>蓄積型（stored）</td><td>投稿したコメントが保存され、後から閲覧した人のページに埋め込まれる。</td></tr><tr><td>DOM型（DOM-based）</td><td>ページのJavaScriptがURLなどから値を読み、HTMLを解釈するAPIへ渡す。たとえばURLの <code>#</code> 以降はHTTP要求の対象に含まれなくても、ページのコードから読める。</td></tr></tbody></table><p>反射型と蓄積型は主にデータの届き方に着目する呼び方です。DOM型はブラウザ側のコードにある実行経路に着目します。サーバーに保存された投稿をJavaScriptが取得して <code>innerHTML</code> に渡す場合は、蓄積型の経路とDOM側のsinkが組み合わさります。<a href="https://community.owasp.org/Types_of_Cross-Site_Scripting" target="_blank" rel="noreferrer">OWASPのXSSの分類</a>、<a href="https://www.rfc-editor.org/rfc/rfc9110.html#section-7.1" target="_blank" rel="noreferrer">RFC 9110のターゲットURI</a></p><h2 id="同じ文字列でも、渡すapiで意味が変わる" tabindex="-1">同じ文字列でも、渡すAPIで意味が変わる <a class="header-anchor" href="#同じ文字列でも、渡すapiで意味が変わる" aria-label="Permalink to &quot;同じ文字列でも、渡すAPIで意味が変わる&quot;">​</a></h2><p><code>div</code> の中にコメントを表示するとします。<code>textContent</code> に代入するとテキストノードになります。<code>innerHTML</code> に代入すると、ブラウザは文字列をHTMLの断片として解析し、要素や属性を作ります。たとえば同じ文字列にボタンと <code>onclick</code> が含まれていると、一方は記号を含む文字として表示され、もう一方はクリック時にコードが動き得るボタンになります。<a href="https://dom.spec.whatwg.org/#dom-node-textcontent" target="_blank" rel="noreferrer">WHATWG DOMのtextContent</a>、<a href="https://html.spec.whatwg.org/multipage/dynamic-markup-insertion.html#the-innerhtml-property" target="_blank" rel="noreferrer">WHATWG HTMLのinnerHTML</a>、<a href="https://html.spec.whatwg.org/multipage/webappapis.html#event-handler-content-attributes" target="_blank" rel="noreferrer">イベントハンドラ</a></p><figure class="study-figure"><img src="'+s+'" alt="同じ固定文字列をdivに渡したとき、textContentはテキストノードを作り、innerHTMLはHTMLを解析してボタンとonclick属性を作る。イベント発生時には許可されているハンドラが実行される。" width="760" height="1020" loading="lazy"><figcaption>文字列の形が同じでも、受け取るAPIがテキストとHTMLのどちらとして処理するかで、できるノードが変わります。<a href="/study/images/browser/xss-data-to-code.svg" target="_blank" rel="noopener noreferrer">テキストとHTMLの分岐を拡大</a></figcaption></figure><p><code>innerHTML</code> の処理では、解析した断片の中の <code>&lt;script&gt;</code> 要素は挿入によって実行されないように扱われます。一方、ボタンの <code>onclick</code> や画像の <code>onerror</code> のように、要素のイベントからコードを実行する経路もあります。<code>&lt;script&gt;</code> の文字だけを取り除く方法では、イベント属性などが残ります。<a href="https://html.spec.whatwg.org/multipage/dynamic-markup-insertion.html#html-parsing-methods" target="_blank" rel="noreferrer">WHATWG HTMLの断片解析と挿入</a>、<a href="https://cheatsheetseries.owasp.org/cheatsheets/Cross_Site_Scripting_Prevention_Cheat_Sheet.html#dangerous-contexts" target="_blank" rel="noreferrer">OWASPの危険なコンテキスト</a></p><h2 id="出力先の構文に合わせて扱う" tabindex="-1">出力先の構文に合わせて扱う <a class="header-anchor" href="#出力先の構文に合わせて扱う" aria-label="Permalink to &quot;出力先の構文に合わせて扱う&quot;">​</a></h2><table tabindex="0"><thead><tr><th>アプリが表示したいもの</th><th>扱い方</th></tr></thead><tbody><tr><td>検索語やコメントをそのまま表示する</td><td>通常の表示用要素に <code>textContent</code> で入れる。サーバーでHTML本文を生成する場合は、テンプレートのHTMLテキスト用エンコードを使う。</td></tr><tr><td>表示用の属性値を設定する</td><td><code>title</code> など用途が決まった属性にDOM APIで値を設定する。テンプレートなら引用符で囲い、HTML属性値の文脈に合わせてエンコードする。</td></tr><tr><td>外部リンクを作る</td><td>URLとして解析し、用途に合うスキームを確認する。必要に応じてホストも照合する。HTMLの属性値をエンコードしても、URLの <code>javascript:</code> スキームは別の検査が必要になる。</td></tr><tr><td>装飾を許す投稿を表示する</td><td>必要な要素や属性、URLの範囲を決め、HTMLを解析するサニタイザで制限してから挿入する。サニタイズ後に別の文字列を連結する場合は、連結した結果の扱いも検査する。</td></tr></tbody></table><p>出力エンコードは、<code>&lt;</code> などをその文脈でデータとして扱わせる変換です。HTML本文、属性値、URL、JavaScriptはそれぞれ構文が異なります。たとえば、通常の表示用要素に <code>textContent</code> を使う方法を、動的に作った <code>&lt;script&gt;</code> の内容に当てはめると、文書への挿入時にコードとして解釈される場合があります。値の検査と、解釈させる構文の選択を分けます。<a href="https://cheatsheetseries.owasp.org/cheatsheets/Cross_Site_Scripting_Prevention_Cheat_Sheet.html#output-encoding" target="_blank" rel="noreferrer">OWASPの出力エンコード・サニタイズ・安全なsink</a>、<a href="https://url.spec.whatwg.org/#dom-url-url" target="_blank" rel="noreferrer">WHATWG URLのURLコンストラクタ</a></p><h2 id="ページで実行されると、どの権限を使うか" tabindex="-1">ページで実行されると、どの権限を使うか <a class="header-anchor" href="#ページで実行されると、どの権限を使うか" aria-label="Permalink to &quot;ページで実行されると、どの権限を使うか&quot;">​</a></h2><p>ページ内で動くコードは、そのページの実行環境で許されたDOMやAPIを利用できます。たとえば同一オリジンのAPIに要求を送り、応答を読んだり状態を変更したりできる場合があります。CORSは別オリジンの応答を公開する条件を定めます。データが同じページのコードになった段階では、まずそのページで何が許されているかを調べます。<a href="/study/browser/same-origin-cors.html">同一オリジンポリシーとCORS</a></p><p><code>HttpOnly</code> はJavaScriptからのCookieの直接読み取りを抑えます。条件に合う要求にはブラウザがCookieを付けるため、ページ内で実行されたコードが、利用者のセッションを伴う要求を送れる場合は残ります。<a href="/study/browser/cookies-and-sessions.html">Cookieとセッション</a>、<a href="https://cheatsheetseries.owasp.org/cheatsheets/Session_Management_Cheat_Sheet.html#httponly-attribute" target="_blank" rel="noreferrer">OWASPのHttpOnly属性の解説</a></p><h2 id="cspでスクリプトの実行を制限する" tabindex="-1">CSPでスクリプトの実行を制限する <a class="header-anchor" href="#cspでスクリプトの実行を制限する" aria-label="Permalink to &quot;CSPでスクリプトの実行を制限する&quot;">​</a></h2><p><strong>CSP</strong>（Content Security Policy）は、ブラウザが文書に適用する方針です。たとえばスクリプトを取得できる場所や、インラインコードを実行できる条件を指定します。<code>script-src</code> はスクリプトの方針を指定します。インラインのイベント属性には、より具体的な <code>script-src-attr</code> を指定できます。属性用の指定がなければ <code>script-src</code>、それもなければ <code>default-src</code> が候補になります。<a href="https://www.w3.org/TR/CSP3/#directive-script-src-attr" target="_blank" rel="noreferrer">W3C CSP Level 3のscript-src-attr</a>、<a href="https://www.w3.org/TR/CSP3/#directive-fallback-list" target="_blank" rel="noreferrer">フォールバックの順序</a></p><p>たとえば、同一オリジンから外部スクリプトを読み込み、イベント属性内のコードを禁止する指定には、次の二つが使えます。同一オリジンで配信できるスクリプトの範囲は、サーバー側の構成にも左右されます。<a href="https://www.w3.org/TR/CSP3/#directive-script-src" target="_blank" rel="noreferrer">W3C CSP Level 3のscript-src</a></p><div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Content-Security-Policy</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> script-src &#39;self&#39;; script-src-attr &#39;none&#39;</span></span></code></pre></div><p>HTMLの解析でボタンが作られた場合、<code>script-src-attr &#39;none&#39;</code> は、その要素の <code>onclick</code> などに書かれたコードの実行を制限します。ボタンの生成や属性の保持とは別の段階であり、DOMに残ったタグや属性を取り除く処理はサニタイズが担います。許可されたスクリプトから <code>addEventListener()</code> で登録したリスナーは、属性内のソースコードを実行する経路とは異なります。<a href="https://www.w3.org/TR/CSP3/#should-block-inline" target="_blank" rel="noreferrer">W3C CSP Level 3のインライン実行の検査</a>、<a href="https://dom.spec.whatwg.org/#dom-eventtarget-addeventlistener" target="_blank" rel="noreferrer">WHATWG DOMのaddEventListener</a></p><figure class="study-figure"><img src="'+n+'" alt="innerHTMLでボタンとonclick属性が作られる。ブラウザは属性のコードをハンドラとして使えるかCSPを検査する。許可されればクリックでコードが動き、script-src-attr noneで拒否される場合はボタンが残り、CSP違反を観察できる。" width="760" height="1100" loading="lazy"><figcaption>ボタンの生成と、そのボタンに含まれるコードの実行は別々に観察できます。<a href="/study/images/browser/csp-inline-handler-flow.svg" target="_blank" rel="noopener noreferrer">CSPが実行を止める箇所を拡大</a></figcaption></figure><h3 id="許可するコードをnonceやハッシュで選ぶ" tabindex="-1">許可するコードをnonceやハッシュで選ぶ <a class="header-anchor" href="#許可するコードをnonceやハッシュで選ぶ" aria-label="Permalink to &quot;許可するコードをnonceやハッシュで選ぶ&quot;">​</a></h3><p><strong>nonce</strong> はサーバーが応答ごとに推測しにくい値を生成し、CSPの許可リストと、許可する <code>&lt;script&gt;</code> の <code>nonce</code> 属性に対応づける方法です。<strong>ハッシュ</strong>は、許可するインラインスクリプトの本文から計算した値を指定する方法です。ハッシュの場合、本文の空白などを変更すると再計算が必要になります。これらでスクリプト要素を許可する判断と、<code>onclick</code> のような属性の判断は区別します。<a href="https://www.w3.org/TR/CSP3/#security-nonces" target="_blank" rel="noreferrer">W3C CSP Level 3のnonce</a>、<a href="https://www.w3.org/TR/CSP3/#match-element-to-source-list" target="_blank" rel="noreferrer">要素とソースリストの照合</a></p><h3 id="ヘッダーとmetaで配信できる範囲" tabindex="-1">ヘッダーとmetaで配信できる範囲 <a class="header-anchor" href="#ヘッダーとmetaで配信できる範囲" aria-label="Permalink to &quot;ヘッダーとmetaで配信できる範囲&quot;">​</a></h3><p>通常は <code>Content-Security-Policy</code> 応答ヘッダーで方針を配信します。静的HTMLでは <code>&lt;head&gt;</code> の早い位置に <code>&lt;meta http-equiv=&quot;Content-Security-Policy&quot;&gt;</code> を置いて適用する方法もあります。metaより前に処理された内容への適用は遡りません。埋め込み元を制限する <code>frame-ancestors</code> や、違反を観測しながら動作を止めずに試す <code>Content-Security-Policy-Report-Only</code> は、HTTP応答ヘッダーで指定します。<a href="https://www.w3.org/TR/CSP3/#policy-delivery" target="_blank" rel="noreferrer">W3C CSP Level 3の配信方法</a></p><h2 id="実践との対応" tabindex="-1">実践との対応 <a class="header-anchor" href="#実践との対応" aria-label="Permalink to &quot;実践との対応&quot;">​</a></h2><p>実践では、親ページと異なるオリジンとして扱われるsandbox付きiframe内で、教材用の固定文字列を使います。同じ文字列を <code>textContent</code> と <code>innerHTML</code> で扱い、CSP付きのケースも比べます。文字として表示されるか、ボタンができるか、イベント属性のコードが動くかを別々に観察します。<a href="/study/practice/browser/xss-csp-observation.html">テキスト挿入、HTML挿入、CSPを比べる</a></p>',28)])])}const b=t(c,[["render",i]]);export{f as __pageData,b as default};
